/**
 * PreToolUse hook on the browser-use screenshot tool: keeps a full-resolution image out of the context.
 *
 * Denies a `browser_screenshot` call with no `max_dim`, pointing at `max_dim: 1280`: a 2x display returns
 * images of several MB, and every later turn re-reads them. A call that names `max_dim` passes.
 *
 * A cost guard, not a security guard: any error lets the call through. Always exits 0.
 *
 * Generated by Claude Code at the user's request.
 */

'use strict';

const { deny, readPayload } = require('./lib/decision');

try {
  const payload = readPayload();
  if (/browser_screenshot$/.test(payload?.tool_name || '') && payload.tool_input?.max_dim == null) {
    deny('Pass `max_dim: 1280` (add `full: true` only when the page below the fold matters): a full-resolution ' +
      'screenshot can weigh several MB, and every later turn re-reads it.');
  }
} catch {
  // a bad payload: the call goes on
}
process.exit(0);
